184	/// Restores a previous `PATH` value on drop, so a test that temporarily
185	/// prepends a fake `moon` shim to `PATH` (see
186	/// `execute_extension_status_succeeds_against_real_repo_fixture` below)
187	/// can't leak that mutation into other tests in this binary even on panic.
188	///
189	/// `PATH` is global, process-wide mutable state, and `cargo test` runs
190	/// `#[tokio::test]` functions from the same test binary concurrently by
191	/// default (separate OS threads sharing one process) -- so every
192	/// PATH-mutating test in this file must also serialize against every other
193	/// one, or they race and corrupt each other's `PATH` mid-test (observed
194	/// empirically: running this suite without `--test-threads=1` produced
195	/// spurious failures from one test's fixture directory bleeding into
196	/// another's assertions). `PATH_MUTEX` provides that serialization;
197	/// `PathGuard` holds the lock for its entire lifetime, only releasing it
198	/// (in `Drop`, after `PATH` has been restored) once the owning test is
199	/// done with it.
200	static PATH_MUTEX: tokio::sync::Mutex<()> = tokio::sync::Mutex::const_new(());
201	
202	struct PathGuard {
203	    previous: Option<std::ffi::OsString>,
204	    _lock: tokio::sync::MutexGuard<'static, ()>,
205	}
206	
207	impl Drop for PathGuard {
208	    fn drop(&mut self) {
209	        // SAFETY: serialized by `PATH_MUTEX` (held by `self._lock` for this
210	        // guard's entire lifetime, released only after this restore runs),
211	        // so no other code in this binary can be concurrently
212	        // reading/writing `PATH` while this executes.
213	        unsafe {
214	            match &self.previous {
215	                Some(v) => std::env::set_var("PATH", v),
216	                None => std::env::remove_var("PATH"),
217	            }
218	        }
219	    }
220	}
221	
222	/// Prepends `dir` to `PATH` and returns a guard that restores the previous
223	/// value when dropped.
224	async fn prepend_to_path(dir: &Path) -> PathGuard {
225	    let lock = PATH_MUTEX.lock().await;
226	    let previous = std::env::var_os("PATH");
227	    let mut new_path = std::ffi::OsString::from(dir);
228	    if let Some(existing) = &previous {
229	        new_path.push(":");
230	        new_path.push(existing);
231	    }
232	    // SAFETY: see `PathGuard::drop` -- serialized via `PATH_MUTEX`, held
233	    // from here until the returned guard is dropped.
234	    unsafe {
235	        std::env::set_var("PATH", &new_path);
236	    }
237	    PathGuard { previous, _lock: lock }
238	}
239	
240	/// Replaces `PATH` entirely with exactly `dirs` (no inheriting the previous
241	/// value) and returns a guard that restores the previous value when
242	/// dropped. Unlike `prepend_to_path`, this is for tests that need to
243	/// guarantee a binary is *absent* -- prepending can't do that, since
244	/// anything already on the ambient test-runner `PATH` (e.g. a real `moon`
245	/// or `git` install) would still be found.
246	async fn set_path_to(dirs: &[&Path]) -> PathGuard {
247	    let lock = PATH_MUTEX.lock().await;
248	    let previous = std::env::var_os("PATH");
249	    let joined = std::env::join_paths(dirs.iter().map(|d| d.as_os_str())).expect("failed to join PATH");
250	    // SAFETY: see `PathGuard::drop` -- serialized via `PATH_MUTEX`, held
251	    // from here until the returned guard is dropped.
252	    unsafe {
253	        std::env::set_var("PATH", &joined);
254	    }
255	    PathGuard { previous, _lock: lock }
256	}
