258	/// Locates the real `which` binary on the ambient (unrestricted) test-runner
259	/// `PATH`, before any test narrows `PATH` down.
260	///
261	/// This crate's `MoonCommandRunner` (the `pdk`-feature impl) pre-checks
262	/// whether a program exists via `warpgate_pdk::command_exists`, which
263	/// itself shells out to `which` (see `runner.rs`'s doc comment on why: a
264	/// program genuinely missing from `PATH` makes warpgate's real
265	/// `exec_command` host function abort the entire plugin call rather than
266	/// returning a catchable error, so `command_exists`/`which` is used to
267	/// sidestep ever calling `exec` for a program known to be absent). Tests
268	/// that restrict `PATH` to prove some *other* program is absent must still
269	/// leave a working `which` on `PATH`, or they'd instead be proving `which`
270	/// is absent -- a different, uninteresting case.
271	fn locate_which_binary() -> PathBuf {
272	    let output = Command::new("which")
273	        .arg("which")
274	        .output()
275	        .expect("failed to invoke `which` to locate itself; `which` must be installed to run this test");
276	    assert!(
277	        output.status.success(),
278	        "`which which` must succeed for this test to isolate a `which`-only PATH entry"
279	    );
280	    PathBuf::from(
281	        String::from_utf8(output.stdout)
282	            .expect("`which which` output must be valid UTF-8")
283	            .trim()
284	            .to_string(),
285	    )
286	}
