310	/// Writes an executable fake `moon` binary to `dir/moon` that answers
311	/// `moon project-graph --json` with a single project rooted at the
312	/// workspace root (`.`) and no dependencies -- just enough for
313	/// `MoonProjectLocator` to discover the fixture package without requiring a
314	/// real, fully-configured moon workspace.
315	///
316	/// The emitted JSON matches the real moon `project-graph --json` schema:
317	/// `{"data":{"<index>":{"id":"...","root":"<absolute>","source":"<relative>","dependencies":[]}}}`.
318	/// The `root` field uses `$(pwd)` so the absolute path is correct regardless
319	/// of which tempdir the sandbox allocates; moon is always executed with
320	/// `cwd = workspace_root` by `MoonCommandRunner`.
321	fn write_fake_moon_binary(dir: &Path) -> PathBuf {
322	    let script = dir.join("moon");
323	    fs::write(
324	        &script,
325	        "#!/bin/sh\n\
326	         if [ \"$1\" = \"project-graph\" ]; then\n\
327	         root=$(pwd)\n\
328	         printf '{\"data\":{\"0\":{\"id\":\"pkg-a\",\"root\":\"%s\",\"source\":\".\",\"dependencies\":[]}}}\\n' \"$root\"\n\
329	         exit 0\n\
330	         fi\n\
331	         exit 1\n",
332	    )
333	    .expect("failed to write fake moon script");
334	
335	    let mut perms = fs::metadata(&script).unwrap().permissions();
336	    std::os::unix::fs::PermissionsExt::set_mode(&mut perms, 0o755);
337	    fs::set_permissions(&script, perms).unwrap();
338	
339	    script
340	}
