498	    fs::write(
499	        root.join("Cargo.toml"),
500	        "[package]\nname = \"pkg-a\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
501	    )
502	    .expect("failed to write fixture Cargo.toml");
503	
504	    let fake_bin_dir = tempfile::tempdir().expect("failed to create fake-bin tempdir");
505	    write_fake_moon_binary(fake_bin_dir.path());
506	    let _path_guard = prepend_to_path(fake_bin_dir.path()).await;
507	
508	    let ext = sandbox.create_extension("callisto").await;
509	
510	    let input = moon_pdk_test_utils::ExecuteExtensionInput {
511	        args: vec!["status".to_string()],
512	        context: ext.create_context(),
513	    };
514	
515	    let output: callisto_moon::ExecuteExtensionOutput = ext
516	        .plugin
517	        .call_func_with("execute_extension", input)
518	        .await
519	        .expect("execute_extension wire call must survive a missing .git directory, not trap");
520	
521	    assert_eq!(
522	        output.exit_code, 0,
523	        "a missing .git directory is not a hard failure -- expected success \
524	         with no last tag, got report: {:#}",
525	        output.report
526	    );
527	    assert!(
