583	        "expected a populated report.error when moon's project-graph output is unparseable, got: {:#}",
584	        output.report
585	    );
586	    let message = output.report["error"]["message"]
587	        .as_str()
588	        .expect("report.error.message must be a string");
589	    assert!(
590	        !message.trim().is_empty(),
591	        "report.error.message must not be empty, got report: {:#}",
592	        output.report
593	    );
594	}
