596	/// Part A #3: `execute_extension` when the `moon` host tool itself is
597	/// entirely absent from `PATH` (distinct from present-but-failing).
598	#[tokio::test(flavor = "multi_thread")]
599	async fn execute_extension_moon_binary_absent_from_path_fails_cleanly() {
600	    resolve_wasm_file();
601	
602	    let sandbox = create_empty_moon_sandbox();
603	
604	    // Replace PATH outright (not prepend) with a directory that has `which`
605	    // (needed by `command_exists`'s pre-check, see `locate_which_binary`'s
606	    // doc comment) but is otherwise guaranteed to contain nothing, so there
607	    // is no possibility of a real `moon` install elsewhere on the ambient
608	    // test-runner PATH being found.
609	    let which_dir = create_which_only_dir();
610	    let _path_guard = set_path_to(&[which_dir.path()]).await;
611	
612	    let ext = sandbox.create_extension("callisto").await;
